fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64> {
    let n = indices.len();
    // Prepare a result vector with the exact capacity we need
    let mut result = Vec::with_capacity(n);

    for i in 0..n {
        // Convert the u8 index to usize
        let row = indices[i] as usize;
        // Select the element at column i in the chosen row
        result.push(choices[row][i]);
    }

    result
}

